INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Raven (Teen Titans)$body$, $body$DC$body$, $body$/characters/raven-teen-titans.png$body$, 57240, 210000, 1145000, 129900, $body$Daughter of Trigon — empathic manipulation, soul-self astral projection, telekinesis, flight, healing; can open portals across dimensions.$body$, $body$Positive emotions can trigger her demonic side; her father Trigon attempts to control her; emotional extremes destabilize her power.$body$, $body$Raven — daughter of the demon Trigon, raised to be his portal to Earth. She chose the Teen Titans instead. That choice defines everything. (Teen Titans variant)$body$, '{"tactical","defensive","speedster"}', 85, 92, 94, $body$Elite$body$, 11, $body${"gadgets":[],"stamina":70,"weapons":[],"battleIQ":53,"counters":["Anti-magic users","Speed blitz attackers","Emotionally manipulative opponents"],"abilities":["Empathic manipulation","Soul-self astral projection","Telekinesis","Flight","Healing","Dimensional portal creation","Mystic offense"],"finishers":["Soul-Self Strike","Dimensional Rift","Empathic Overload"],"lethality":67,"loreNotes":"Raven's demonic heritage makes her a powerful ally, but her emotional instability can be exploited. (Teen Titans variant)","powerTier":8,"archetypes":["mage","ranged-blaster","reality-hax"],"regenLevel":"moderate","signatures":["Soul-Self Strike","Dimensional Rift","Empathic Overload"],"weaknesses":["Positive emotions trigger demonic side","Emotional extremes destabilize powers","Vulnerable to anti-magic attacks"],"combatStyle":["zoning","tactical spell use","range control"],"temperament":"controlled","haxAbilities":["soul manipulation","reality warping","teleportation","life force drain"],"mobilityType":["flight","teleportation"],"notableFeats":["Defeated Trigon's influence and banished him from Earth (Teen Titans: The Judas Contract).","Sealed dimensional rifts threatening reality (Teen Titans Go!).","Healed teammates from near-death injuries using empathic powers (Teen Titans: Trouble in Tokyo)."],"specialRules":["Can exploit unusual win conditions","Emotionally unstable powers"],"preferredRange":"long","intelligenceType":"magical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Raven (Teen Titans)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Nova (Richard Rider)$body$, $body$Marvel$body$, $body$/characters/nova-richard-rider.png$body$, 702300, 5424000, 86600, 702300, $body$Full Nova Force — one of the most powerful energy sources in Marvel; flight at superluminal speed; energy blasts that can destroy planets; Worldmind interface.$body$, $body$The full Nova Force is physically and mentally taxing to maintain; Richard Rider carries the weight of an entire destroyed civilization.$body$, $body$Richard Rider absorbed the full Nova Force — the combined power of the entire Nova Corps — when Xandar was destroyed. As Nova Prime, he is a one-man army capable of planetary-scale destruction. (Richard Rider variant)$body$, '{"aggressive","tactical","defensive","speedster"}', 48, 56, 36, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":85,"weapons":[],"battleIQ":80,"counters":["energy nullification","psychological manipulation","high-speed precision attacks"],"abilities":["Nova Force manipulation","superluminal flight","energy blasts","enhanced durability","Worldmind interface"],"finishers":["Nova Force Blast","Planetary Destruction Beam","Worldmind Tactical Strike"],"lethality":70,"loreNotes":"Nova Prime's mastery of the Nova Force makes him a devastating force in cosmic conflicts. (Richard Rider variant)","powerTier":8,"archetypes":["speedster","glass-cannon","tactician"],"regenLevel":"moderate","signatures":["Nova Force Blast","Planetary Destruction Beam","Worldmind Tactical Strike"],"weaknesses":["mental strain","emotional burden","energy depletion"],"combatStyle":["power-overwhelming","precision-strike","cosmic-awareness"],"temperament":"adaptive","haxAbilities":["energy manipulation","cosmic awareness"],"mobilityType":["flight","super speed"],"notableFeats":["Held the Cancerverse back with Star-Lord (Marvel Comics, Thanos Imperative #6).","Destroyed a planet with Nova Force energy (Marvel Comics, Nova #25).","Absorbed the full Nova Force after Xandar's destruction (Marvel Comics, Nova #1).","Defeated Annihilus in combat (Marvel Comics, Annihilation #6)."],"specialRules":["mentally taxing to maintain full Nova Force","Worldmind assists in combat"],"preferredRange":"variable","intelligenceType":"cosmic"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Nova (Richard Rider)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Nightwing (Dick Grayson)$body$, $body$DC$body$, $body$/characters/nightwing-dick-grayson.png$body$, 42667, 468200, 468200, 38160, $body$Master acrobat and martial artist trained by Batman; skilled in escrima stick combat; exceptional detective and charismatic leader.$body$, $body$No superhuman powers; avoids killing, limiting options; protective nature can lead to vulnerabilities.$body$, $body$Dick Grayson, formerly Robin and now Nightwing, is a hero who combines Batman's training with his own unique charisma and leadership. He protects Blüdhaven with unmatched skill and heart. (Dick Grayson variant)$body$, '{"tactical","speedster"}', 98, 0, 2, $body$Elite$body$, 11, $body${"gadgets":[],"stamina":85,"weapons":["Escrima sticks"],"battleIQ":85,"counters":["Strong melee fighters","Long-range attackers","High-tech gadgets"],"abilities":["Master acrobatics","Escrima stick combat","Exceptional detective skills","Leadership","Stealth expertise"],"finishers":["Nightwing's Strike","Flying Grayson"],"lethality":20,"loreNotes":"Nightwing's acrobatics and detective skills make him one of the most versatile members of the Bat-family. (Dick Grayson variant)","powerTier":1,"archetypes":["martial-expert","speedster"],"regenLevel":"none","signatures":["Nightwing's Strike","Flying Grayson"],"weaknesses":["Vulnerable to heavy hitters","Low lethality","No superhuman durability"],"combatStyle":["tactical","speedster","martial-expert"],"temperament":"heroic","haxAbilities":[],"mobilityType":["acrobatic movement"],"notableFeats":["Defeated Blockbuster in hand-to-hand combat (Nightwing Vol. 2 #93).","Led the Teen Titans against Trigon (New Teen Titans Vol. 1).","Outmaneuvered Deathstroke in combat (Nightwing Vol. 2 #112).","Protected Blüdhaven from multiple criminal organizations.","Survived and escaped from the Court of Owls (Nightwing Vol. 4 #7)."],"specialRules":["Utilizes acrobatics for evasive maneuvers","Charismatic leader"],"preferredRange":"close","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Nightwing (Dick Grayson)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Huntress (Helena)$body$, $body$DC$body$, $body$/characters/huntress-helena.png$body$, 300000, 400000, 4000000, 400000, $body$Lethal crossbow marksmanship — near-Batman-level combat training; no moral restraint against killing; Catholic vigilante with a personal vendetta against the mob.$body$, $body$No superpowers; emotional vendetta against the mob clouds judgment; often at odds with Batman's no-kill rule.$body$, $body$Helena Bertinelli is the Huntress, a vigilante born from mafia tragedy who fights crime with a crossbow and a lethal ruthlessness that Batman struggles to accept. (Helena variant)$body$, '{"balanced"}', 90, 20, 10, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":70,"weapons":["Crossbow"],"battleIQ":75,"counters":["High-durability opponents","Stealth techniques","Emotionally manipulative enemies"],"abilities":["Lethal crossbow marksmanship","Near-Batman-level combat skills","Stealth tracking","Ambush tactics","Mob hunting expertise"],"finishers":["Crossbow Execution","Vigilante Justice","Silent Shot"],"lethality":80,"loreNotes":"Huntress's lethal methods often put her at odds with Batman and other heroes, but her effectiveness is undeniable. (Helena variant)","powerTier":3,"archetypes":["hunter","tactician"],"regenLevel":"none","signatures":["Crossbow Execution","Vigilante Justice","Silent Shot"],"weaknesses":["Emotional trauma from past","Can be overzealous","No superhuman durability"],"combatStyle":["aggressive","tactical","guerrilla-precision"],"temperament":"cold","haxAbilities":[],"mobilityType":["ground movement"],"notableFeats":["Defeated multiple mob bosses single-handedly (DC Comics: Huntress).","Held her own against Batman in combat (DC Comics: Birds of Prey).","Successfully infiltrated and dismantled criminal organizations (DC Comics: Huntress).","Saved Gotham from a mob war using her tactical skills (DC Comics: Huntress)."],"specialRules":["No qualms about lethal force","Excels in urban environments"],"preferredRange":"ranged","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Huntress (Helena)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Storm (Ororo Munroe)$body$, $body$Marvel$body$, $body$/characters/storm-ororo-munroe.png$body$, 15000, 2000000, 400000, 50000, $body$Complete mastery over weather, including lightning, wind, blizzards, and tornadoes.$body$, $body$Claustrophobia can compromise her concentration and effectiveness.$body$, $body$Ororo Munroe, also known as Storm, is a mutant with goddess-like control over the weather. Her leadership and tactical skills make her a cornerstone of the X-Men. (Ororo Munroe variant)$body$, '{""}', 78, 95, 40, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":80,"weapons":[],"battleIQ":85,"counters":["Energy absorbers","Anti-weather manipulators","Close-range fighters"],"abilities":["Weather manipulation","Lightning generation","Wind control","Temperature manipulation","Flight"],"finishers":["Lightning Storm","Tornado Strike","Blizzard Barrage"],"lethality":30,"loreNotes":"Storm's powers are versatile and devastating, but her claustrophobia can be exploited in confined spaces. (Ororo Munroe variant)","powerTier":3,"archetypes":["tactician","glass-cannon"],"regenLevel":"none","signatures":["Lightning Storm","Tornado Strike","Blizzard Barrage"],"weaknesses":["Claustrophobia","Loss of powers in contained spaces","Over-reliance on weather manipulation"],"combatStyle":["guerrilla-precision","ranged-control","adaptive-strategy"],"temperament":"disciplined","haxAbilities":["weather manipulation","flight"],"mobilityType":["flight","wind-assisted movement"],"notableFeats":["Defeated Cyclops in a duel for leadership of the X-Men (Uncanny X-Men #201)","Created a massive hurricane to stop an invading army (X-Men Annual #5)","Generated lightning powerful enough to destroy Sentinels (X-Men #98)","Saved the planet by stabilizing the weather during a global crisis (X-Men #150)"],"specialRules":["Claustrophobia reduces effectiveness","Environmental advantage in open spaces"],"preferredRange":"ranged","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Storm (Ororo Munroe)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Jean Grey (Phoenix)$body$, $body$Marvel$body$, $body$/characters/jean-grey-phoenix.png$body$, 900000, 2250000, 3000000, 2250000, $body$Omega-level telepath and telekinetic, capable of reshaping matter and energy on a universal scale as the host of the Phoenix Force.$body$, $body$Phoenix Force can overwhelm her; emotional trauma triggers loss of control; immense psychic strain.$body$, $body$Jean Grey is one of the most powerful mutants alive, wielding unparalleled telepathic and telekinetic abilities. As the host of the Phoenix Force, she walks the fine line between heroism and cosmic destruction. (Phoenix variant)$body$, '{"aggressive","tactical","defensive","speedster"}', 42, 95, 97, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":80,"weapons":[],"battleIQ":63,"counters":["mental shielding","cosmic-level durability","erratic pressure"],"abilities":["Telepathy","Telekinesis","Reality warping","Energy manipulation","Flight","Matter manipulation"],"finishers":["Phoenix Flare","Cosmic Disruption","Mental Overload"],"lethality":70,"loreNotes":"Jean Grey's connection to the Phoenix Force makes her a cosmic-level threat, capable of reshaping the universe. (Phoenix variant)","powerTier":10,"archetypes":["reality-hax","telepath","glass-cannon"],"regenLevel":"absolute","signatures":["Phoenix Flare","Cosmic Disruption","Mental Overload"],"weaknesses":["Phoenix Force instability","Emotional trauma","Psychic strain"],"combatStyle":["zoning","power-overwhelming","ranged-pressure"],"temperament":"balanced","haxAbilities":["reality warping","mind control","durability negation","matter manipulation","teleportation"],"mobilityType":["flight","teleportation"],"notableFeats":["Destroyed an entire planet while under Phoenix Force influence (X-Men comics, Dark Phoenix Saga).","Defeated Gladiator, a cosmic-level opponent, with telekinesis (X-Men comics, various issues).","Resurrected herself from death using the Phoenix Force (X-Men comics, Phoenix Resurrection).","Held off the combined forces of the X-Men and Avengers during the Phoenix Five storyline (Avengers vs. X-Men)."],"specialRules":["Can attack minds or senses directly","Phoenix Force amplifies all abilities","Reality warping affects universal scale"],"preferredRange":"variable","intelligenceType":"cosmic"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Jean Grey (Phoenix)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Reverse Flash (Eobard Thawne)$body$, $body$DC$body$, $body$/characters/reverse-flash-eobard-thawne.png$body$, 86600, 6816000, 140000, 47227, $body$Negative Speed Force; vibration through matter; time travel; creates temporal paradoxes; obsessed with Barry Allen.$body$, $body$The obsession with the Flash makes him predictable; Negative Speed Force is more volatile than the real thing.$body$, $body$Eobard Thawne — a man from the 25th century who hated his hero so much he became the villain of history itself. His mastery of time and speed makes him nearly unstoppable. (Eobard Thawne variant)$body$, '{"aggressive","tactical","speedster"}', 70, 24, 94, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":95,"weapons":[],"battleIQ":74,"counters":["Hope manipulation","Speed negation","Temporal anchors"],"abilities":["Negative Speed Force manipulation","Time travel","Vibration through matter","Speed stealing","Temporal paradox creation","Enhanced reflexes","Reality manipulation","Energy projection"],"finishers":["Temporal Rupture","Speed Force Implosion","Vibrational Strike"],"lethality":90,"loreNotes":"Reverse Flash's mastery of time manipulation makes him one of the most dangerous speedsters in existence. (Eobard Thawne variant)","powerTier":10,"archetypes":["speedster","reality-hax","tactician"],"regenLevel":"moderate","signatures":["Temporal Rupture","Speed Force Implosion","Vibrational Strike"],"weaknesses":["Obsession with Barry Allen","Volatility of Negative Speed Force","Predictable patterns due to fixation"],"combatStyle":["speed blitz","time manipulation","precision strikes"],"temperament":"cunning","haxAbilities":["time manipulation","reality warping","durability negation","speed stealing"],"mobilityType":["super speed","time travel","vibration-based movement"],"notableFeats":["Killed Barry Allen's mother and framed his father (Flashpoint).","Created a temporal paradox to erase Barry Allen from existence (The Flash Vol. 3 #8).","Defeated multiple speedsters simultaneously using Negative Speed Force (The Flash Vol. 5 #50).","Manipulated time to rewrite history in his favor (The Flash: Rebirth)."],"specialRules":["Can manipulate time to undo defeats","Negative Speed Force disrupts conventional speedsters"],"preferredRange":"variable","intelligenceType":"scientific"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Reverse Flash (Eobard Thawne)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Thor (God of War)$body$, $body$God of War$body$, $body$/characters/thor-god-of-war.png$body$, 3500000, 2200000, 22000, 3500000, $body$Thunder god strength; Mjolnir hammer; Norse berserker rage$body$, $body$Drunken arrogance; predicted to die in Ragnarok$body$, $body$God of War's Thor — massive Aesir thunder god, brutal hammer-wielding berserker.$body$, '{"aggressive","unstoppable"}', 75, 80, 50, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":90,"weapons":["Mjolnir"],"battleIQ":65,"counters":["agility","ranged-pressure"],"abilities":["Thunder god strength","Mjolnir bisects mountains","Lightning storms","Berserker rage"],"finishers":["Mjolnir Skull-Crusher","Thunder Slam","Storm Crash"],"lethality":95,"loreNotes":"Aesir thunder god from Norse myth.","powerTier":9,"archetypes":["bruiser","berserker","god"],"regenLevel":"high","signatures":["Mjolnir Skull-Crusher","Thunder Slam"],"weaknesses":["Drunken arrogance","Norse fated death"],"combatStyle":["bruiser","power-overwhelming","close-range"],"temperament":"aggressive","haxAbilities":["lightning manipulation"],"mobilityType":["flight (with Mjolnir)","sprint"],"notableFeats":["Killed multiple Jotnar with Mjolnir","Battle with Kratos"],"specialRules":[],"mentalDefense":"high","preferredRange":"melee","intelligenceType":"warrior"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Thor (God of War)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Link (BOTW)$body$, $body$Zelda$body$, $body$/characters/link-botw.png$body$, 18360, 31001, 29307, 18360, $body$Master Sword sacred light power, Triforce of Courage blessing, champion abilities — Daruk's Protection, Revali's Gale, Mipha's Grace, Urbosa's Fury.$body$, $body$Chosen hero destiny means some foes are predetermined, limited magic stamina.$body$, $body$The Hero of Time and Hyrule's eternal champion. Armed with the Master Sword and Triforce of Courage, he always rises to defeat Ganon and protect Hyrule. (BOTW variant)$body$, '{"aggressive","close-quarters"}', 34, 24, 16, $body$Standard$body$, 9, $body${"gadgets":["Hookshot","Bombs","Bow and arrows"],"stamina":80,"weapons":["Master Sword","Hylian Shield"],"battleIQ":65,"counters":["Cunning enemies","Magic resistance","Physical barriers"],"abilities":["Master Sword sacred light power","Triforce of Courage blessing","Champion abilities","Enhanced agility","Magic resistance"],"finishers":["Triforce Smash","Sword Spin Attack","Light Arrow Barrage"],"lethality":50,"loreNotes":"Link's courage and resourcefulness make him a formidable hero, even against overwhelming odds. (BOTW variant)","powerTier":5,"archetypes":["martial-expert","hero"],"regenLevel":"low","signatures":["Triforce Smash","Sword Spin Attack","Light Arrow Barrage"],"weaknesses":["Overconfidence","Reliance on artifacts","Vulnerability to dark magic"],"combatStyle":["aggressive","close-quarters","guerrilla-precision"],"temperament":"heroic","haxAbilities":["magic resistance","enhanced durability"],"mobilityType":["acrobatic movement"],"notableFeats":["Defeated Ganon multiple times across timelines.","Mastered the Master Sword and Hylian Shield.","Saved Hyrule from Calamity Ganon (Breath of the Wild).","Utilized Champion abilities to overcome powerful foes.","Restored peace to Hyrule in numerous eras."],"specialRules":["Can channel the power of the Triforce","Gains abilities from allies"],"preferredRange":"close","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Link (BOTW)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Thanos (Infinity Gauntlet)$body$, $body$Marvel$body$, $body$/characters/thanos-infinity-gauntlet.png$body$, 10224000, 10104, 1836200, 2754300, $body$Infinity Gauntlet reality rewriting, cosmic energy projection, tactical genius, immense physical power, virtually indestructible.$body$, $body$Subconscious desire to lose, Infinity Stones can be taken or separated, hubris.$body$, $body$The Mad Titan who gathered the Infinity Stones to reshape reality. Thanos is a cosmic-level threat whose power dwarfs most beings in the universe. (Infinity Gauntlet variant)$body$, '{"aggressive","tactical","defensive","reality-warper"}', 78, 93, 74, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":95,"weapons":["Infinity Gauntlet"],"battleIQ":86,"counters":["speedsters","reality warpers","mental manipulators"],"abilities":["cosmic energy projection","reality warping","immense strength","durability","tactical genius"],"finishers":["Snap of Doom","Cosmic Crush","Reality Rewrite"],"lethality":87,"loreNotes":"Thanos's power is nearly unmatched, but his subconscious desire to lose can be exploited. (Infinity Gauntlet variant)","powerTier":10,"archetypes":["tank","tactician","cosmic overlord"],"regenLevel":"absolute","signatures":["Infinity Snap","Cosmic Beam","Planetary Crush"],"weaknesses":["hubris","Infinity Stones can be separated","subconscious self-sabotage"],"combatStyle":["power-overwhelming","strategic adaptation","cosmic dominance"],"temperament":"cold","haxAbilities":["reality warping","durability negation","teleportation","matter manipulation"],"mobilityType":["teleportation","flight"],"notableFeats":["Wielded the Infinity Gauntlet to erase half of all life in the universe (Marvel Comics: Infinity Gauntlet).","Defeated the Avengers and cosmic entities in battle (Marvel Comics: Infinity War).","Destroyed planets with physical strength alone (Marvel Comics: Thanos solo series).","Survived attacks from cosmic-level beings like Galactus (Marvel Comics: Thanos vs Galactus).","Outsmarted cosmic entities like Eternity and Death (Marvel Comics: Infinity Gauntlet)."],"specialRules":["scales with Infinity Stones","subconscious desire to lose"],"preferredRange":"variable","intelligenceType":"cosmic"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Thanos (Infinity Gauntlet)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Homelander (TV)$body$, $body$The Boys$body$, $body$/characters/homelander-tv.png$body$, 6816000, 804800, 7316, 6816000, $body$Homelander possesses heat vision capable of melting steel, flight at mach speed, near-invulnerability, and enhanced senses.$body$, $body$Psychological fragility and pathological need for approval; fear of being perceived as weak.$body$, $body$Homelander is the most powerful Supe on Earth, with unmatched physical strength and durability. His heat vision and flight make him a devastating force in combat. (TV variant)$body$, '{"aggressive","defensive","long-range","speedster","profanity"}', 14, 46, 6, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":90,"weapons":[],"battleIQ":17,"counters":["Psychological manipulation","High-damage energy attacks","Team-based strategies"],"abilities":["Heat vision","Flight","Super strength","Enhanced senses","Near-invulnerability"],"finishers":["Heat Vision Blast","Aerial Slam","Brutal Overpower"],"lethality":80,"loreNotes":"Homelander's overwhelming power is tempered by his psychological vulnerabilities, making him dangerous but unstable. (TV variant)","powerTier":5,"archetypes":["bruiser","tank"],"regenLevel":"moderate","signatures":["Heat Vision Blast","Aerial Slam","Brutal Overpower"],"weaknesses":["Psychological fragility","Pathological need for approval","Fear of being perceived as weak"],"combatStyle":["damage-trading pressure","power-overwhelming"],"temperament":"balanced","haxAbilities":["heat vision"],"mobilityType":["flight"],"notableFeats":["Destroyed a plane mid-flight with heat vision (The Boys, Season 1)","Lifted a car effortlessly (The Boys, Season 1)","Survived a direct explosion without injury (The Boys, Season 2)"],"specialRules":["Heat vision can melt steel at range","Flight enables high mobility","Near-invulnerability makes him difficult to harm"],"preferredRange":"variable","profanityStyle":"moderate — uses strong language when mask slips, controlled in public","intelligenceType":"street"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Homelander (TV)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Saitama (Serious Mode)$body$, $body$One Punch Man$body$, $body$/characters/saitama-serious-mode.png$body$, 15000000, 15000000, 35000, 15000000, $body$Limitless physical power capable of defeating any opponent with a single punch.$body$, $body$Boredom and lack of motivation often prevent him from engaging seriously in fights.$body$, $body$Saitama, the One Punch Man, trained so hard he became invincible, losing his hair in the process. His overwhelming strength has left him searching for a worthy challenge. (Serious Mode variant)$body$, '{"aggressive","defensive","close-quarters","speedster"}', 68, 20, 70, $body$Cosmic$body$, 14, $body${"gadgets":[],"stamina":100,"weapons":[],"battleIQ":30,"counters":["Time manipulators","Reality warpers","Illusionists"],"abilities":["Serious Punch","Limitless power potential","Damage immunity","Shockwave generation","Enhanced reflexes"],"finishers":["Serious Series Punch","Normal Punch","Consecutive Normal Punches"],"lethality":20,"loreNotes":"Saitama's power defies conventional scaling, making him a comedic yet unstoppable force. (Serious Mode variant)","powerTier":10,"archetypes":["bruiser","tank"],"regenLevel":"absolute","signatures":["Serious Series Punch","Normal Punch","Consecutive Normal Punches"],"weaknesses":["Boredom in fights","Lack of motivation","Holds back by default"],"combatStyle":["power-overwhelming","close-quarters","precision-striking"],"temperament":"cold","haxAbilities":["damage immunity","shockwave generation"],"mobilityType":["super speed","leaping"],"notableFeats":["Split the sky with a Serious Punch (One Punch Man manga, Chapter 85)","Defeated Boros, a planetary-level threat, with a single punch (One Punch Man anime, Episode 12)","Survived being kicked to the moon and returned in seconds (One Punch Man anime, Episode 12)","Destroyed a massive meteor with one punch (One Punch Man anime, Episode 7)"],"specialRules":["Can defeat any opponent in one punch","Comedic immunity to harm","Power scales infinitely"],"preferredRange":"melee","intelligenceType":"street"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Saitama (Serious Mode)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Stormfront (Comics)$body$, $body$The Boys$body$, $body$/characters/stormfront-comics.png$body$, 300000, 187500, 200000, 300000, $body$Lightning projection — kills with bioelectricity; supersonic flight; extreme durability; propaganda and mass psychological manipulation; survived severe injury and continued fighting.$body$, $body$Fire is particularly effective; sustained burns overwhelm her regeneration; ideological rigidity makes her predictable in political scenarios.$body$, $body$The first supe created by Compound V — born in Nazi Germany and used ever since. Stormfront's real weapon is not lightning. It's a century of psychological warfare and mass manipulation. The lightning just closes the argument. (Comics variant)$body$, '{"balanced"}', 28, 8, 8, $body$Elite$body$, 11, $body${"gadgets":[],"stamina":75,"weapons":[],"battleIQ":27,"counters":["Fire-based attacks","Magic disruption","High-durability opponents"],"abilities":["Lightning projection","Supersonic flight","Enhanced durability","Psychological manipulation","Regeneration"],"finishers":["Lightning Strike","Bioelectric Blast","Thunderous Charge"],"lethality":70,"loreNotes":"Stormfront's ideological rigidity makes her predictable in certain scenarios. (Comics variant)","powerTier":3,"archetypes":["glass-cannon","speedster"],"regenLevel":"moderate","signatures":["Bioelectric Blast","Thunderous Charge","Lightning Strike"],"weaknesses":["Fire vulnerability","Predictable ideological rigidity","Limited hax capabilities"],"combatStyle":["guerrilla-precision","power-overwhelming","methodical"],"temperament":"cold","haxAbilities":["regeneration"],"mobilityType":["flight","super speed"],"notableFeats":["Survived severe injuries and continued fighting (The Boys TV series).","Manipulated public opinion through propaganda.","Defeated numerous opponents using lightning projection.","Displayed supersonic flight capabilities."],"specialRules":["Lightning attacks can incapacitate opponents","Regeneration allows survival of severe injuries","Psychological manipulation enhances control over groups"],"preferredRange":"variable","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Stormfront (Comics)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Soldier Boy (Comics)$body$, $body$The Boys$body$, $body$/characters/soldier-boy-comics.png$body$, 1717500, 37440, 6736, 2754300, $body$Soldier Boy's nuclear chest blast can permanently strip Supes of their powers, and his Compound V-enhanced physiology grants near-indestructibility.$body$, $body$PTSD from Soviet experimentation; overconfidence; blast requires charging; vulnerable to strong psychics.$body$, $body$Soldier Boy is the original superhero, active since WWII. His nuclear chest blast is a unique ability capable of permanently depowering Supes. (Comics variant)$body$, '{"aggressive","arrogant","defensive"}', 78, 70, 60, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":85,"weapons":[],"battleIQ":78,"counters":["Psychic manipulation","High-speed combatants","Strategic teamwork"],"abilities":["Nuclear chest blast","Super strength","Near-indestructibility","Combat mastery","Immortality from Compound V"],"finishers":["Nuclear Blast","Power Overload","Combat Mastery Strike"],"lethality":90,"loreNotes":"Soldier Boy's nuclear blast makes him a unique threat to Supes, but his overconfidence can be exploited. (Comics variant)","powerTier":3,"archetypes":["tank","bruiser"],"regenLevel":"moderate","signatures":["Nuclear Blast","Power Overload","Combat Mastery Strike"],"weaknesses":["Blast requires charging","Vulnerable to strong psychics","Overconfidence in abilities"],"combatStyle":["power-overwhelming","aggressive","defensive"],"temperament":"sadistic","haxAbilities":["power nullification","durability negation"],"mobilityType":[],"notableFeats":["Depowered Kimiko with nuclear blast (The Boys, Season 3)","Survived Soviet experimentation and torture (The Boys, Season 3)","Destroyed a building with his chest blast (The Boys, Season 3)"],"specialRules":["Nuclear blast can strip powers permanently","Immortal due to Compound V","Combat mastery from WWII experience"],"preferredRange":"mid","intelligenceType":"street"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Soldier Boy (Comics)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Gladiator (Kallark)$body$, $body$Marvel$body$, $body$/characters/gladiator-kallark.png$body$, 6816000, 3616000, 20667, 6816000, $body$Near-unlimited strength tied to confidence; heat vision; freeze breath; invulnerability; flight at light speed; Shi'ar Imperial Guard leader.$body$, $body$His power level is directly linked to his confidence — self-doubt physically weakens him; a single moment of hesitation can cost him everything.$body$, $body$Kallark the Gladiator is the Praetor of the Shi'ar Imperial Guard — the most powerful warrior in an empire that spans galaxies. His power is staggering but entirely psychological. (Kallark variant)$body$, '{"aggressive","defensive","long-range","speedster"}', 48, 56, 36, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":85,"weapons":[],"battleIQ":65,"counters":["psychological manipulation","precision strikes","energy nullification"],"abilities":["heat vision","freeze breath","super strength","invulnerability","light-speed flight"],"finishers":["Heat Vision Blast","Freeze Breath Strike","Confidence Surge"],"lethality":80,"loreNotes":"Gladiator's confidence-based power makes him a unique and unpredictable combatant. (Kallark variant)","powerTier":8,"archetypes":["tank","bruiser","berserker"],"regenLevel":"moderate","signatures":["Heat Vision Blast","Freeze Breath Strike","Confidence Surge"],"weaknesses":["self-doubt","psychological manipulation","hesitation"],"combatStyle":["power-overwhelming","confidence-based","direct-strike"],"temperament":"battle-hungry","haxAbilities":["invulnerability","heat vision"],"mobilityType":["flight","super speed"],"notableFeats":["Traded blows with Thor and Hulk (Marvel Comics, Thor #445).","Destroyed a planet with a single punch (Marvel Comics, War of Kings #3).","Defeated the Annihilators in combat (Marvel Comics, Annihilators #4).","Held his own against Thanos (Marvel Comics, Infinity #6)."],"specialRules":["confidence directly scales power","self-doubt weakens"],"preferredRange":"variable","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Gladiator (Kallark)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Nova (Sam Alexander)$body$, $body$Marvel$body$, $body$/characters/nova-sam-alexander.png$body$, 327740, 2531200, 86600, 327740, $body$Full Nova Force — one of the most powerful energy sources in Marvel; flight at superluminal speed; energy blasts that can destroy planets; Worldmind interface.$body$, $body$The full Nova Force is physically and mentally taxing to maintain; Richard Rider carries the weight of an entire destroyed civilization.$body$, $body$Richard Rider absorbed the full Nova Force — the combined power of the entire Nova Corps — when Xandar was destroyed. As Nova Prime, he is a one-man army capable of planetary-scale destruction. (Sam Alexander variant)$body$, '{"aggressive","tactical","defensive","speedster"}', 48, 56, 36, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":85,"weapons":[],"battleIQ":80,"counters":["energy nullification","psychological manipulation","high-speed precision attacks"],"abilities":["Nova Force manipulation","superluminal flight","energy blasts","enhanced durability","Worldmind interface"],"finishers":["Nova Force Blast","Planetary Destruction Beam","Worldmind Tactical Strike"],"lethality":70,"loreNotes":"Nova Prime's mastery of the Nova Force makes him a devastating force in cosmic conflicts. (Sam Alexander variant)","powerTier":8,"archetypes":["speedster","glass-cannon","tactician"],"regenLevel":"moderate","signatures":["Nova Force Blast","Planetary Destruction Beam","Worldmind Tactical Strike"],"weaknesses":["mental strain","emotional burden","energy depletion"],"combatStyle":["power-overwhelming","precision-strike","cosmic-awareness"],"temperament":"adaptive","haxAbilities":["energy manipulation","cosmic awareness"],"mobilityType":["flight","super speed"],"notableFeats":["Held the Cancerverse back with Star-Lord (Marvel Comics, Thanos Imperative #6).","Destroyed a planet with Nova Force energy (Marvel Comics, Nova #25).","Absorbed the full Nova Force after Xandar's destruction (Marvel Comics, Nova #1).","Defeated Annihilus in combat (Marvel Comics, Annihilation #6)."],"specialRules":["mentally taxing to maintain full Nova Force","Worldmind assists in combat"],"preferredRange":"variable","intelligenceType":"cosmic"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Nova (Sam Alexander)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$Hyperion (Squadron Supreme)$body$, $body$Marvel$body$, $body$/characters/hyperion-squadron-supreme.png$body$, 3616000, 3616000, 42667, 3616000, $body$Atomic vision; near-unlimited strength and speed; flight; cosmic awareness; survived universal resets; power drawn from atomic energy.$body$, $body$Can be weakened by argonite radiation; carries the psychological weight of being the sole survivor of dead universes.$body$, $body$Hyperion is the last survivor of a dead universe — Marvel's Superman analog, but without Clark Kent's warmth. He has punched through dimensions and held two colliding universes apart with his bare hands. (Squadron Supreme variant)$body$, '{"aggressive","defensive","speedster"}', 48, 56, 36, $body$Cosmic$body$, 13, $body${"gadgets":[],"stamina":95,"weapons":[],"battleIQ":70,"counters":["radiation-based attacks","psychological manipulation","energy nullification"],"abilities":["atomic vision","cosmic awareness","super strength","super speed","flight"],"finishers":["Atomic Vision Burst","Dimensional Punch","Universe Hold"],"lethality":75,"loreNotes":"Hyperion's cosmic awareness and raw power make him a devastating force in planetary-scale conflicts. (Squadron Supreme variant)","powerTier":8,"archetypes":["tank","bruiser","cosmic"],"regenLevel":"moderate","signatures":["Atomic Vision Burst","Dimensional Punch","Universe Hold"],"weaknesses":["argonite radiation","psychological burden","emotional detachment"],"combatStyle":["power-overwhelming","direct-strike","cosmic-awareness"],"temperament":"cold","haxAbilities":["cosmic awareness","dimensional manipulation"],"mobilityType":["flight","super speed"],"notableFeats":["Held two colliding universes apart (Marvel Comics, Avengers #44).","Survived universal resets (Marvel Comics, Squadron Supreme #1).","Destroyed a planet with atomic vision (Marvel Comics, Hyperion #3).","Punched through dimensional barriers (Marvel Comics, Exiles #77)."],"specialRules":["resistant to universal resets","argonite radiation weakens"],"preferredRange":"variable","intelligenceType":"cosmic"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$Hyperion (Squadron Supreme)$body$);
INSERT INTO characters ("name", "universe", "image_url", "strength", "speed", "intelligence", "durability", "special_ability", "weaknesses", "description", "behavior_tags", "skill", "energy_projection", "hax", "tier", "power_gap_index", "v3_profile") SELECT $body$The Question (Vic Sage)$body$, $body$DC$body$, $body$/characters/the-question-vic-sage.png$body$, 7904, 6736, 3664000, 9104, $body$Faceless appearance causes psychological unease; master martial artist trained by Richard Dragon; investigative genius.$body$, $body$Paranoia occasionally compromises operations; lacks ranged combat options.$body$, $body$Vic Sage, known as The Question, is a faceless investigator and martial artist who uncovers conspiracies and secrets. (Vic Sage variant)$body$, '{"tactical"}', 28, 8, 8, $body$Elite$body$, 12, $body${"gadgets":[],"stamina":75,"weapons":[],"battleIQ":90,"counters":["Brute strength","Direct confrontation","Psychological resilience"],"abilities":["Faceless disguise","Master martial artist","Investigative genius","Psychological manipulation","Conspiracy detection"],"finishers":["Questioning Blow","Mystery Unmasked","Conspiracy Strike"],"lethality":10,"loreNotes":"The Question's investigative skills and psychological tactics make him a unique combatant. (Vic Sage variant)","powerTier":3,"archetypes":["martial-expert","infiltrator"],"regenLevel":"none","signatures":["Faceless Strike","Conspiracy Unraveled","Martial Precision"],"weaknesses":["Physical weakness compared to stronger opponents","Lack of ranged options","Overthinking situations"],"combatStyle":["tactical","psychological"],"temperament":"calculating","haxAbilities":["psychological manipulation"],"mobilityType":["ground movement"],"notableFeats":["Uncovered major conspiracies in Gotham.","Defeated skilled martial artists in combat.","Solved complex mysteries with limited resources.","Instilled fear in opponents using psychological tactics."],"specialRules":["Faceless appearance instills fear","Expert in psychological manipulation"],"preferredRange":"close","intelligenceType":"tactical"}$body$::jsonb WHERE NOT EXISTS (SELECT 1 FROM characters WHERE name = $body$The Question (Vic Sage)$body$);
